# -*- coding: utf-8 -*-
"""批次K（主观题 466~491，共 26 题）：参考答案 -> 题目解析 + 标准答案。
用法：python D:\\dev-tools\\apply_batch.py D:\\dev-tools\\batch_K_data.py"""
NEW = {
    466: ("逗号表达式是 C 的常用考点，从求值规则展开：①逗号运算符是 C 中优先级最低的运算符（比赋值 = 还低），表达式 `(j=4,k=8,l=16,m=32)` 从左到右依次求值每个子表达式，整个表达式的值等于最后一个子表达式的值——依次执行 j=4、k=8、l=16、m=32 后，括号整体取值 m=32 赋给 i，输出 32；②左侧子表达式要有副作用（赋值/自增等）才有意义，否则只是被求值后丢弃；③括号不可省：`int i=(j=4,k=8,l=16,m=32);` 与去掉括号的 `int i=j=4,k=8;` 完全是两回事（后者是逗号分隔的多项声明，i 只被赋 4），正因逗号优先级最低，不加括号语义就变；④若写成 `i = j=4, k=8;` 则解析为 `(i=j=4), k=8;`，i 为 4。易错点：把括号内的逗号当成分隔符、忽视优先级最低这一点。", "输出 32。括号内是逗号表达式：从左到右依次求值 j=4、k=8、l=16、m=32，逗号表达式取最后一个子表达式的值，故 m=32 赋给 i；逗号运算符优先级最低（比赋值还低），括号不可省。"),
    467: ("考点是“宏是预处理阶段的文本替换、代入后按优先级重新结合”：实参 k+m 原样代入 SQR(X) 的宏体 (X*X) 后，表达式展开为 `a /= (k+m*k+m)/(k+m*k+m);`——并不存在“先加后乘”的分组（实参没有括号保护），而是按运算符优先级重新结合：k+m*k+m = 2+1*2+1 = 5（不是 (2+1)²=9），分子、分母都等于 5，5/5=1，a = 10/1 = 10。经典对照（面试常问口径）：若宏写成不带参数括号的 `#define SQR(X) X*X`，展开为 `a /= k+m*k+m/k+m*k+m;` = 2+1*2+(1/2)+1*2+1，整数除法 1/2=0，得 2+2+0+2+1=7，10/7=1——很多资料里“答案 1”来自这个变体；本题宏体带括号 (X*X)，答案就是 10。结论：宏参数代入后不能保证整体先算，必须给参数也加括号，正确写法 `#define SQR(X) ((X)*(X))`（此时 9/9=1、10/1=10，才是真正的“平方语义”）。易错点：按函数调用思维把 k+m 先算成一组相除。", "输出 10。宏在预处理阶段做文本替换，k+m 原样代入后为 `a /= (k+m*k+m)/(k+m*k+m);`，按优先级先乘后加得 (2+1*2+1)=5，分子分母都是 5，5/5=1，a=10/1=10。要点：宏参数必须加括号，正确写法 `#define SQR(X) ((X)*(X))`；若宏体改成无括号的 X*X，结果才是 10/7=1。"),
    468: ("推演关键在“先取值、后自增”的生效时机与 && 的短路：①`int j = i++;`——先取 i 的原值 1 赋给 j，i 自增为 2（此时 j=1）；②`(i > j++)`——先用 j 的当前值 1 参与比较，2>1 为真，比较完成后 j 才自增为 2；③&& 左边为真、不短路，继续求 `(i++ == j)`——i++ 取当前值 2 与 j=2 比较、相等为真，比较完成后 i 自增为 3；④if 成立执行 `i += j`，i = 3+2 = 5。要点：①j++/i++ 是“先取值、后自增”，同一表达式中自增何时生效要按“取值—比较—生效”顺序推演；②&& 有短路特性（左边为假则右边不执行），本题左边为真所以右边执行了。易错点：把 (i>j++) 误当“j 先自增再比较”会一路算错。", "i 最后等于 5（此时 j 为 2）。推演：`j=i++` 后 j=1、i=2；`(i>j++)` 用 j=1 比较（2>1 真）后 j 变 2；`(i++==j)` 用 i=2 与 j=2 比较（相等为真）后 i 变 3；if 成立执行 `i+=j` 得 3+2=5。注意“先取值后自增”的生效时机与 && 短路特性。"),
    469: ("引用（reference）的本质是“已存在对象的别名”——语言层面不产生新对象、通常不占用独立的可寻址存储（底层以地址实现，可理解为“自动解引用的常量指针”），对引用的一切操作就是对所绑定对象的操作，且一旦绑定不能改绑。声明与使用的注意点：①定义时必须初始化，不存在“空引用”；②绑定后不能改指向——给引用赋值等于给原对象赋值；③不存在“引用的引用”（`int&&` 是右值引用、含义不同），也不存在引用的数组；④不能绑定字面量/临时值这类非左值（常量引用 `const T&` 除外，且它只读）；⑤不能返回局部变量的引用（悬空引用），返回引用必须确保对象生命周期足够长；⑥引用不支持指针运算、也不能为 NULL，用起来比指针安全、简洁；⑦sizeof(引用) 得到的是所指对象的大小，不是地址大小；⑧底层虽用地址实现，但语言语义与指针不同——引用不是对象、无法重新定位，而指针是独立对象、可改指向。易错点：说“引用就是指针”忽略语义差异；漏掉必须初始化与不能改绑。", "引用是已存在对象的别名：语言层面不产生新对象，对引用的操作就是对绑定对象的操作，必须初始化（无空引用）、一旦绑定不能改绑。注意点：①不能改指向（给引用赋值即改原对象）；②不能返回局部变量引用（悬空）；③不能绑定字面量/临时值（const T& 常量引用除外）；④不存在引用的引用与引用数组；⑤不支持指针运算、不能为 NULL，比指针安全简洁；⑥sizeof(引用)=所指对象大小；⑦底层以地址实现（可理解为自动解引用的常量指针），但引用不是对象、无法重新定位。"),
    470: ("常引用即 `const T&`，“既避免拷贝、又禁止修改”，典型使用时机：①函数参数传大对象——`const 类类型&` 免拷贝（效率）+ 防误改（安全），是 C++ 传参的默认推荐；②需要绑定临时对象/字面量时——普通引用不能绑右值，const T& 可以，如 `void f(const std::string& s)` 允许传 \"abc\"（经隐式转换生成临时 string），并把该临时量的生命周期延长到引用作用域结束；③表达接口语义——告诉调用者“我只读不写”（如 `compare(const T& a, const T& b)`）；④拷贝构造/赋值运算符的形参必须写 `const T&`（避免无限递归拷贝、支持绑定常对象）；⑤返回引用时若调用者不应修改，也返回 const T&。易错点：常引用只保证“不能通过这个名字改”，原对象本身仍可变；const 引用绑定临时量延长的是该临时量生命周期，不要把它当“万能安全引用”到处返回。", "常引用即 `const T&`，典型场景：①函数参数传大对象——避免拷贝 + 防误改，是 C++ 传参的默认推荐；②需要绑定临时对象/字面量时——普通引用不能绑右值，const T& 可以（如 `void f(const std::string& s)` 允许传 \"abc\" 产生的临时 string），并延长临时量生命周期到引用作用域结束；③表达“只读不写”的接口语义（如 `compare(const T&, const T&)`）；④拷贝构造/赋值运算符形参必须 const T&（避免递归拷贝、支持常对象）；⑤返回引用且调用者不应修改时也返回 const T&。注意：常引用只保证不能通过该名字修改、原对象仍可变。"),
    471: ("三条输出考察三个点——数组名即地址、指针比较的是地址、字面量合并：①str1、str2 是两个独立的数组对象，名字在表达式中退化为各自的首地址，str1==str2 比较的是地址→不同→false（比较内容须用 strcmp 或 std::string）；②str3、str4 是 const 数组，同样是两个独立对象、地址不同→false——const 只限制“通过该名字修改”，不改变它们是两个对象的事实；③str5、str6 是指针，初始化时都指向同一字符串字面量 \"abc\"——编译器通常把相同字面量合并存储（同一份数据），两个指针指向同一地址→true。注意：C++ 标准并不保证相同字面量一定合并（是实现可选的优化），主流编译器（GCC/Clang/MSVC）都会合并；写代码不应依赖 str5==str6 为 true 这个“特性”。易错点：把数组名比较当成内容比较；误以为标准强制合并字面量。", "依次输出 false、false、true（boolalpha 会把布尔值打印成 true/false）。①str1、str2 是两个独立数组对象，比较的是各自首地址→false；②str3、str4 是 const 数组，同样是两个独立对象、地址不同→false；③str5、str6 是指向字符串字面量的指针，相同字面量通常被编译器合并存储、指向同一地址→true（标准不强制合并，不应依赖）。"),
    472: ("main() 只是“用户程序的约定入口”，进程真正的启动与结束由运行库、加载器与操作系统驱动——CRT 启动代码（_start → __libc_start_main → main）在 main 之前早已运行，而在 main 之外还有大量不受其控制（或先于其后）的动作：①全局/静态对象在 main() 之前构造（全局类实例的构造函数、std::cout 初始化），main 返回后还有全局对象析构与 atexit 注册函数；②静态初始化与动态链接——加载器完成动态库装载、符号重定位、动态库初始化函数（.init_array/DLL 入口）的调用，均与 main 无关；③中断/信号处理——硬件中断触发 ISR、内核在任意时刻向进程投递信号，二者独立于 main 的控制流；④其它线程——线程无论由谁创建都可独立运行，main 结束后守护/后台线程仍可能继续处理；⑤运行库/编译器的隐式动作——异常处理机制、模板实例化、静态构造顺序相关的运行库初始化等。易错点：只想到“main 里写的代码”，忽略构造/析构、加载器、中断与线程这些“main 之外”的来源。", "不是。举例：①全局/静态对象在 main() 之前构造、main 返回后有全局析构与 atexit 函数；②动态库装载、符号重定位与动态库初始函数由加载器完成；③硬件中断的 ISR 与信号处理函数在任意时刻由硬件/内核触发；④其它线程独立于 main 运行（守护/后台线程）；⑤CRT 启动代码 _start → __libc_start_main → main 等运行库隐式调用。一句话：main() 只是用户程序入口，进程的启动/结束流程由运行库与操作系统驱动。"),
    473: ("先总述存储区规则：栈——局部/自动变量与函数参数（含指针变量本身）；堆——malloc/new 申请的内存；静态区 .data/.bss——全局变量、文件级 static、函数内 static（已显式初始化归 .data，未初始化归 .bss）；只读段 .rodata——字符串字面量等常量。逐项展开（以 32 位平台为例；64 位下所有指针与 double 都变为 8 字节）：Node 类型本体不占运行内存，sizeof(Node)=2×4(两个指针)+1024(buf)+1(a)+3(填充)+4(ib)+2(header)+2(填充)+4(p)+4(buf2)+12(fun[3])=1064 B；文件级 `static double m=2.1` 8 B 在静态区 .data（程序启动即存在直到进程结束）；全局 `int data=0` 4 B 在静态区（已显式初始化通常 .data）全程有效；`int *p` 指针本身 4 B 在栈，p 所指向的 malloc(sizeof(int)) 内存 4 B 在堆、由 free(p) 释放；`char *buf=\"helloworld\"` 指针 4 B 在栈，字面量 \"helloworld\"（含 '\\0' 共 11 B）在只读段 .rodata、不可修改；函数内 `static double m=10.0` 8 B 在静态区 .data（不是栈！只初始化一次、生命周期到程序结束、作用域限本函数）；`Node *node` 指针 4 B 在栈、节点本体 1064 B 在堆、free(node) 释放；`char buf[10]` 10 B 与 `int i=0` 4 B 在栈；函数内 `extern int data;` 只是声明、不新分配空间（仍是全局静态区那份）。另注：原答案提示两处易错——①宏名大小写需一致（`size` 与 `SIZE` 混用会编译不过；本库所列代码两处均为大写）；②main 中 `char *buf = \"helloworld\";` 后又 `char buf[10];` 同名重复定义，属编译错误（应改为 buf10 或先注释其一）。", "以 32 位平台为例：文件级 `static double m=2.1` 8B 在静态区 .data；全局 `int data` 4B 在静态区（已显式初始化通常 .data）；`int *p` 指针 4B 在栈、其 malloc 的 4B 在堆（free 释放）；`char *buf=\"helloworld\"` 指针 4B 在栈、字面量 11B（含 '\\0'）在只读段 .rodata 不可修改；函数内 `static double m=10.0` 8B 在静态区 .data（不是栈，只初始化一次）；`Node *node` 指针 4B 在栈、节点本体 1064B 在堆（free 释放）；`char buf[10]` 10B 与 `int i` 4B 在栈；`extern int data;` 只是声明不占新空间。sizeof(Node)=1064=2×4+1024+1+3 填充+4+2+2 填充+4+4+12。总结：栈放局部/自动变量与参数，堆放 malloc/new，静态区（.data/.bss）放全局与 static，只读段放字符串字面量等常量。"),
    474: ("按“先判条件、再取分支”两步：'B' 的 ASCII 码是 66，处于 'A'(65) 与 'Z'(90) 之间，条件 `ch>='A' && ch<='Z'` 成立，三目运算取 `ch+12` 分支：66+12=78，78 对应大写字母 'N'（'A'=65，N 是第 14 个字母，65+13=78）。要点：①字符参与算术按 ASCII 码（或平台字符集）计算，结果再按字符解释；②三目运算符 `条件?表达式1:表达式2` 只对选中的分支求值、另一分支不求值；③“字母加密/凯撒位移”类题常用这一写法。易错点：把 'B'+12 当字符串拼接；忘记 'A' 是 65。", "值为 'N'。'B' 的 ASCII 码是 66，条件 65≤66≤90 成立，执行 ch+12：66+12=78，78 即大写字母 'N'。要点：字符按 ASCII 参与算术、三目只对选中分支求值。"),
    475: ("按“宏展开→按优先级重新结合→逐步求值”推演：`e = N(a++, b+M(c,d));` 中 N 的宏体 `(x)*y` 只给 x 加了括号、y 没有括号保护，代入后展开为 `(a++)*b+M(c,d)`；M 的宏体 `x>y?x:y` 也无整体括号，继续展开为 `(a++)*b+c>d?c:d`。按优先级（乘除高于加减、加减高于比较、比较高于三目）结合为 `((a++)*b+c) > d ? c : d`：先算 (a++)*b——a++ 取 3、a 变 4，3×4=12；12+c=17；17>d(6) 为真，取 c=5 赋给 e。关键点：①N 的宏体未给 y 加括号，b+M(c,d) 代入后 M 展开的 c>d?c:d 与外层 +、> 重新结合；②宏参数 a++ 只出现一次，副作用仅一次；③正确写法应给每个参数和整体加全括号（`#define N(x,y) ((x)*(y))`、`#define M(x,y) ((x)>(y)?(x):(y))`），那时结果为 3*(4+6)=30。易错点：忽略宏展开的优先级重组、按直觉先算 M(c,d)=6。", "输出 5（执行完后 a=4）。展开为 `e=(a++)*b+c>d?c:d`，按优先级即 `((a++)*b+c)>d?c:d`：(a++)*b=3×4=12（a 变 4），12+5=17>6 为真，取 c=5。根因：宏 N、M 的宏体未给参数/整体加全括号；加全括号后结果会变成 30。"),
    476: ("`char *s = \"abcde\";` 中 s 是字符指针、初始指向字面量 \"abcde\" 的首字符 'a'；`s += 2` 让指针前移 2 个字节（char 占 1 字节），指向 'c'；`printf(s);` 以 s 作为格式串，从 'c' 开始打印直到 '\\0'，输出 cde。要点与风险：①printf(s) 直接拿变量当格式串不是好习惯——若字符串里含 %d 等格式符会按格式解析（本题 \"cde\" 无 %，恰好安全），规范写法是 `printf(\"%s\", s)`；②\"abcde\" 是字符串字面量、位于只读段，`*s='x'` 之类写操作会崩溃；③指针运算以所指类型为单位，char 指针 +2 就是 +2 字节。易错点：误以为 s+=2 是把字符串内容改掉。", "输出 cde。s 指向 \"abcde\" 首字符，`s+=2` 后指向 'c'，printf(s) 从 'c' 打印到 '\\0' 得 cde（char 指针 +2 即 +2 字节）。注意 printf(s) 用变量当格式串有风险（应写 `printf(\"%s\", s)`），且字面量在只读段不可写。"),
    477: ("考察 %.2f、%4ld、%% 三个格式控制：①`%.2f` 保留两位小数——1.8495 存为 float 时实际约为 1.84949994，第三位小数是 9，四舍五入到两位得 1.85；②`%4ld` 按最小宽度 4 打印长整型 32——数字占 2 位、左边补 2 个空格（默认右对齐），得 \"  32\"；③`%%` 输出一个普通 % 字符。注意点：%4ld 中的 4 是最小宽度而非精度，左对齐用 %-4ld；浮点数直接格式化/比较要注意二进制表示误差（本题值正好进位到 1.85）。完整输出 `1.85,   32%`（逗号后共 3 个空格：格式串内 1 个 + 宽度补 2 个）。易错点：把宽度 4 当精度、漏算 %% 或空格数。", "第一空 1.85，第二空 \"  32%\"（32 前两个空格、结尾一个百分号），完整输出 `1.85,   32%`。%.2f 四舍五入到两位小数；%4ld 按最小宽度 4 右对齐、左补 2 个空格；%% 输出一个 %。"),
    478: ("本题考查“虚函数动态绑定 vs 非虚函数静态绑定”：①`pfa=&fa; pfa->foo();`——对象是 Father，虚函数 foo 走 Father 版本，输出 M；②`pfa->fun();`——fun 不是虚函数，编译期按指针的静态类型 Father 绑定调用，输出 S；③`pfa=&ch;` 基类指针指向派生类对象后 `pfa->foo();`——foo 是虚函数，运行期按实际对象类型动态绑定到 Child::foo，输出 T；④`pfa->fun();`——fun 非虚，仍按静态类型 Father 调用，输出 S（不是 R！），派生类的同名非虚函数只是隐藏了基类版本。延伸：只有被声明为 virtual 且通过指针/引用调用才发生运行时多态；若基类析构不是虚函数，delete pfa 也存在同样问题；同名非虚函数建议加 override 检查或避免与基类同名。易错点：以为派生类重写了同名函数就都会多态调用。", "依次输出 M、S、T、S。①foo 是虚函数：pfa 指向 Father 时调用 Father::foo→M；指向 Child 时动态绑定 Child::foo→T；②fun 非虚：始终按指针静态类型 Father 绑定→两次都输出 S（Child::fun 只是隐藏，不会经基类指针被调用）。要点：只有 virtual + 指针/引用调用才有运行时多态。"),
    479: ("编译时多态（静态多态）在编译期就确定调用目标：函数重载、运算符重载、模板实例化；运行时多态（动态多态）依赖虚函数表 vtable，运行期按对象的动态类型找到实际函数。运行时多态生效三要素：①基类中声明虚函数；②派生类覆盖（override）；③通过基类指针或引用调用——若用直接对象（`Father f = ch;` 发生切片）或按值调用，多态不生效。易错点：把“函数重载”当成运行时多态；忘记运行时多态三要素或 vtable 机制。", "编译时多态通过函数重载（或运算符重载、模板）实现；运行时多态通过继承 + 虚函数（含动态绑定、vtable 机制）实现。注意运行时多态三要素：基类声明虚函数、派生类覆盖、经基类指针/引用调用。"),
    480: ("按删除逻辑推演：q 从头结点出发、循环结束时指向第 i-1 个结点（前驱），待删结点为 q->next。横线(1)先保存待删结点指针：`p = q->next;`；横线(2)让前驱跨过待删结点指向其后继，补全为 `q->next = p->next;`（题面排版“q->next = p; ____”处补 ->next，整句成为 q->next = p->next;），最后 free(p) 释放。要点：①有头结点时删除第 1 个元素也无需改 head（头结点永远在）；②先保存 p、再改链的顺序不能反，否则会丢失后继；③工程实现应判空（p==NULL 说明 i 越界）并注意堆/内存池差异。易错点：先改链后保存会丢后继；漏掉 free。", "横线(1)填 `p = q->next;`；横线(2)处补 `->next`，使整句成为 `q->next = p->next;`（前驱 q 跨过待删结点 p 指向其后继），最后 `free(p)` 释放。要点：q 是第 i-1 个结点的前驱、p 为待删结点；先保存再改链的顺序不能反。"),
    481: ("牛吃草问题的通法——“总消耗 = 原有草量 + 每天生长量×天数”，先消元求日生长量与原有草量、再代入求解。设初始草量 S、每天新长草量 g（每头牛每天吃 1 份）：由两次“吃尽”列式 27×6=162=S+6g、23×9=207=S+9g；两式相减 45=3g 得 g=15，代回得 S=162−90=72。养 21 头牛设吃 T 天：21T = S+gT = 72+15T → 6T=72 → T=12 天。易错点：直接按“牛数×天数成反比”算（忽略草在生长），或把 g 与牛数混淆。", "12 天。设原有草量 S、每天新长草量 g（每头牛每天吃 1 份）：27×6=162=S+6g、23×9=207=S+9g，相减得 g=15、S=72；养 21 头：21T=72+15T → 6T=72 → T=12 天。"),
    482: ("按“宏→关键字→校验”逐处找错：①第 04 行宏参数未加括号——`#define FUN(m,n) ((m/n))` 中 m、n 代入的是整表达式 a+b、a-b，展开成 `((a+b/a-b))`，按优先级算成 a+b/a−b（先除后加），与要求的 (a+b)/(a−b) 不符，应改为 `#define FUN(m,n) ((m)/(n))`；②第 09 行关键字/变量名大小写错误——`Return (Value);` 应为 `return (value);`，C 语言区分大小写，Return 不是关键字、Value 也是未定义标识符，编译直接报错；③第 17 行校验条件不完整——题目要求 x≠y 且 z≠y，只要 x==y 或 z==y 任一个成立分母就为 0，条件应为 `if(x==y || z==y)`；原写法 `x==y && y==z` 只在两者同时成立时才报错、漏检大量非法输入（运行时除零得 inf/nan）。其他可提及：main 标准写法应为 `int main(void)` 并 return 0；math.h 未使用。易错点：只看出大小写而漏掉宏缺括号与校验条件。", "主要有 3 处错误：①第 04 行宏参数缺括号：((m/n)) 展开后为 ((a+b/a-b))、算成 a+b/a−b，应改为 ((m)/(n))；②第 09 行应为 `return (value);`——Return/Value 大小写错误（C 区分大小写、编译不过）；③第 17 行应为 `if(x==y || z==y)`——要求 x≠y 且 z≠y，原条件漏检除零输入。另可提 main 应写 int main(void)。"),
    483: ("对照“每轮选最小、放到已排序区末尾”的选择排序流程找错：①第 08 行内层循环 `j<size; j--` 方向反了，应为 `j++`——j 递减会永不终止并越界访问 a[负数]，属未定义行为/崩溃；②第 10 行比较方向反了：要找最小应为 `if(min_value > a[j])`——原写法 `min_value < a[j]` 实际选出最大值、结果变成降序（与函数名/题意不符）；③第 19 行拼写错误：`a[min_inex]` 中 min_inex 未定义（第 03 行声明 min_inex、第 06 行又用 min_index），属编译错误，应与声明一起统一为 min_index。修正后逻辑：外层控制已排序区边界，内层在未排序区间找最小值下标，若 i≠min_index 则交换 a[i]。补充：选择排序 O(n²)、不稳定。", "3 处错误：①第 08 行 `j--` 应为 `j++`（否则死循环并越界访问）；②第 10 行 `<` 应为 `>`——找最小写反、实际选出最大，成降序；③第 19 行 `min_inex` 拼写错误，应与第 03/06 行统一为 `min_index`（编译错误）。修正后为标准选择排序（O(n²)、不稳定、升序）。"),
    484: ("推理链条：设车牌为 aabb（a≠b，a 取 1~9、b 取 0~9），数值 N=1100a+11b=11×(100a+b)。N 为完全平方数且含因子 11，故必能被 11² 整除 → 100a+b 需再被 11 整除；而 100a+b ≡ a+b (mod 11)，即要求 a+b 是 11 的倍数。枚举 a+b=11 的候选：(2,9)=2299、(3,8)=3388、(4,7)=4477、(5,6)=5566、(6,5)=6655、(7,4)=7744、(8,3)=8833、(9,2)=9922（a=1 时 b=10 非法）；逐一开方验证：√2299≈47.9、√3388≈58.2、√4477≈66.9、√5566≈74.6、√6655≈81.6、√7744=88、√8833≈94.0、√9922≈99.6——只有 7744 是完全平方数。结论：车号 7744。易错点：忘记“含 11 的平方数须被 11² 整除”这一整除性质、硬试全部四位数。", "车号是 7744（7744=88²）。设车牌 aabb，N=11×(100a+b)；因 N 是完全平方数且含 11，须 11² 整除 N → a+b 为 11 的倍数；枚举候选 (2,9)~(9,2)（2299、3388、4477、5566、6655、7744、8833、9922），只有 7744 开方得整数 88。"),
    485: ("作用：①定义接口/规范——在抽象基类中声明“必须由派生类实现”的函数、明确继承者契约；②禁止基类被实例化——含纯虚函数的类是抽象类、不能创建对象，强制通过派生类使用；③为运行时多态提供统一入口（基类指针/引用动态绑定到各派生类实现），并便于在基类先写好通用流程（模板方法模式）。实现：`virtual 返回类型 函数名(参数) = 0;`。要点：①抽象类可以有数据成员和普通成员函数、其构造函数可以被子类调用；②派生类必须覆盖纯虚函数，否则派生类仍是抽象类、不能实例化；③纯虚函数可以给出函数体（=0 后仍可定义），派生类可用 `Base::f()` 显式调用基类版本；④抽象类作指针/引用使用没有限制；⑤析构函数常声明为虚（保证 delete 基类指针时正确析构）；⑥“纯虚函数 + 虚析构”是 C++ 面向接口编程的常规做法（也可用纯虚析构）。易错点：以为纯虚函数绝对不能有函数体。", "作用：①定义接口契约——声明必须由派生类实现的函数；②含纯虚函数即抽象类、禁止基类实例化；③为运行时多态提供统一入口（基类指针动态绑定），便于写通用流程（模板方法）。实现：`virtual 返回类型 函数名(参数) = 0;`。要点：派生类不覆盖则仍是抽象类；纯虚函数可带函数体、可用 `Base::f()` 调用；接口类常配虚析构。"),
    486: ("vector 是连续内存的动态数组、list 是双向链表（每元素独立分配节点），选型看操作模式：①频繁随机访问（`v[i]`）→vector——O(1) 随机访问、连续内存 CPU 缓存/预取友好；list 随机访问 O(n) 且节点分散、缓存不友好；②频繁在中间插入/删除→list——已知位置插删 O(1)、只改指针；vector 中间插删要搬移后续元素 O(n)、还可能触发扩容重分配；③内存与开销——vector 每元素无额外开销、扩容成倍申请并搬移（可 reserve 预留）；list 每节点多两个指针+独立分配（碎片/分配开销大）；④只在尾部增删→vector 的 push_back/pop_back 均摊 O(1)，首选 vector（最通用的默认容器；两端操作用 deque）；⑤迭代器稳定性——vector 扩容后所有迭代器/引用失效；list 插删只影响被删元素、其它迭代器有效（适合需要稳定引用的场景）。结论：默认用 vector，只有“明确的中间插删热点、且不需随机访问”才考虑 list；要按序且频繁插删也可考虑 set/map。易错点：不加分析地背“list 插删快”，忽略查找代价与内存开销。", "vector：连续内存动态数组——随机访问 O(1)、缓存友好，中间插入/删除 O(n)（搬移元素、可能扩容）。list：双向链表——已知位置插删 O(1)、迭代器稳定（只影响被删元素），但随机访问 O(n)、每节点多两个指针且独立分配、缓存不友好。选型：频繁随机访问、只在尾部增删用 vector（默认选它，可 reserve）；频繁中间插删、需要稳定引用用 list；两端操作用 deque。"),
    487: ("读复杂声明用“右左法则”（从标识符出发先往右、再往左，遇括号跳出去），逐条解读：①`void *(*(fp1)(int))[10];`——fp1(int) 是函数（参数 int），* 表示返回指针，[10] 表示指向含 10 个元素的数组，元素类型 void*，即“fp1 是返回『指向含 10 个 void* 数组的指针』的函数”（按题面写法如此；经典教材版本多一个星号 `void *(*(*fp1)(int))[10];`，含义变为“指向函数的指针”——只差一个星号，答题时可顺带说明）；②`float (*(*fp2)(int,int,float))(int);`——fp2 是指针，指向函数（参数 int,int,float），该函数返回一个函数指针，被返回的指针指向“参数 int、返回 float”的函数；③`typedef double (*(*(*fp3)())[10])();` + `fp3 a;`——a 是指针，指向无参数函数，该函数返回“指向含 10 个元素数组的指针”，元素是“无参数、返回 double 的函数指针”（一层层剥：a→指针→函数()→数组[10]→指针→函数()→double）；④`int (*(*f4)())[10]();`——该写法本身编译不过（GCC 报 declaration of 'f4' as array of functions，数组元素不能是函数）；按经典答案意图应修正为 `int (*(*f4())[10])();`——f4 是无参函数，返回“指向含 10 个元素数组的指针”，元素是“无参数、返回 int 的函数指针”；答题先指出不合法、再给修正含义。总结技巧：右左法则。易错点：从外往里硬读、被括号绕晕。", "①fp1：函数（参数 int），返回“指向含 10 个 void* 元素的数组的指针”（经典同题多一个 * 时为指向函数的指针）；②fp2：指向函数（int,int,float）的指针，返回“指向『参数 int、返回 float』的函数指针”；③a：指针，指向无参函数，返回“指向 10 元素数组的指针”，元素为 double(*)() 函数指针；④f4：题面写法非法（数组元素不能是函数），按经典意图修正为“无参函数返回指向含 10 个 int(*)() 元素的数组的指针”。技巧：右左法则（先右后左、遇括号跳出）。"),
    488: ("按“精度、成本、可移植性”对比常用方法：①C 标准库 time()/localtime()/strftime()（time.h）——跨平台简单、秒级精度，适合日志时间戳/界面显示；缺点：时区/夏令时依赖环境，localtime/gmtime 返回静态缓冲（非线程安全，多线程用 localtime_r）；②clock()——返回进程消耗的 CPU 时间（不是墙钟时间），适合测算法 CPU 耗时，不适合取“当前时刻”；③POSIX gettimeofday()——微秒级墙钟时间、Linux/Unix 常用；受系统时间调整影响、非单调，测耗时可能因 NTP 校时“倒退”；④POSIX clock_gettime(CLOCK_REALTIME/CLOCK_MONOTONIC/CLOCK_MONOTONIC_RAW)——纳秒级；CLOCK_MONOTONIC 是单调时钟（不受校时影响），是测耗时/定时的首选；实时时间用 CLOCK_REALTIME；⑤C++11 std::chrono::system_clock/steady_clock——类型安全、跨平台；steady_clock 单调适合计时、system_clock 可转 time_t 供显示（需 C++11）；⑥Windows GetSystemTime/GetTickCount64/QueryPerformanceCounter——GetTickCount64 毫秒级系统运行时间、QPC 高精度计时；平台可移植性差；⑦嵌入式——SysTick/定时器计数器（HAL_GetTick、TIM）做毫秒/微秒计时，RTC 提供掉电保持的日历时间。选型建议：记录“时刻”用 system_clock/localtime；测量“时长”用单调时钟（chrono::steady_clock / CLOCK_MONOTONIC / HAL_GetTick），避免系统时间被调整导致测量出错。易错点：用 wall clock 测耗时、忽视线程安全。", "常用方法：①time()/localtime()/strftime()——跨平台、秒级、简单，适合时间戳（localtime 非线程安全，用 localtime_r）；②clock()——进程 CPU 时间，适合测算法耗时、不取墙钟；③gettimeofday()——微秒级墙钟，受校时影响、非单调；④clock_gettime(CLOCK_REALTIME/MONOTONIC)——纳秒级，MONOTONIC 单调、测耗时首选；⑤C++11 chrono 的 system_clock/steady_clock——类型安全，steady 单调适合计时；⑥Windows GetTickCount64/QueryPerformanceCounter；⑦嵌入式 SysTick/定时器计数器与 RTC。选型：记录时刻用 system_clock，测量时长用单调时钟（steady_clock/CLOCK_MONOTONIC），避免用墙钟测耗时。"),
    489: ("二者都会让 CPU 暂停当前执行流、保存现场并跳转到处理程序（都可用统一的向量/门机制），区别主要在来源、同步性与处理时机：①来源——中断（interrupt）来自处理器外部的异步事件：外设（定时器、串口、GPIO、DMA 等）在任意时刻发请求、与当前指令无因果关系；异常（exception）由当前正在执行的指令引起、是同步的——如除零、非法指令、访问权限错误、缺页、系统调用（软中断）、断点等；②触发时机——中断可在指令之间被采样响应（异步到达）；异常一定在某条指令执行时产生、与指令对应；③处理与返回——中断处理完成后一般返回被中断的指令继续执行；异常可能无法直接返回：故障类有的可修复（缺页修好页表后重试同一条指令）、有的必须终止进程（不可恢复致命异常）；陷阱类（如系统调用、int3）返回下一条指令；④分类——异常通常分故障 fault（可重试）、陷阱 trap（返回下一条指令）、终止 abort（不可恢复）；中断分可屏蔽/不可屏蔽、软/硬中断；⑤嵌入式视角——Cortex-M 把外部中断（IRQn）与系统异常（HardFault、SVC、SysTick）统一编址，但语义上仍按上述区分。易错点：只答“来源不同”不展开、忘记返回行为差异。", "相同点：都使 CPU 暂停当前流、保存现场并跳到处理程序（统一向量/门机制）。区别：①来源——中断来自处理器外部的异步事件（定时器/串口等外设，与当前指令无因果）；异常由当前指令引起、同步（除零、非法指令、缺页、系统调用、断点）；②返回——中断处理完返回被中断的指令；异常可修复时重试原指令（缺页）、陷阱类返回下一条、致命异常终止进程；③分类——异常分 fault/trap/abort，中断分可屏蔽/不可屏蔽、软/硬；Cortex-M 将 IRQn 与系统异常统一编址。"),
    490: ("背后的准则是指针变量的大小只取决于系统的地址空间宽度（字长），与所指类型无关——32 位机器地址是 32 位，因此 char*、int*、void*、函数指针（多数平台）都是 4 字节；64 位机器则是 8 字节。易错点：①以为 char* 是 1 字节（那是所指对象 'a' 的大小，sizeof(*pszChar) 才等于 1）；②以为 int* 是 4 字节而 char* 是 1 字节；③要记牢结论“指针大小与机器字长有关、与所指向的类型无关”（sizeof(char*) 在 64 位上为 8）。", "两个都占 32 位（4 字节）。指针变量的大小只取决于系统地址空间宽度（字长）、与所指类型无关——32 位机器上 char*、int*、void* 都是 4 字节，64 位机器上为 8 字节。勿把“char* 所指对象为 1 字节”当成指针大小。"),
    491: ("从“分配 + 构造”与“只分配原始内存”的本质区别展开：①本质——new 是运算符（语言内置、可重载 operator new），分配内存并调用构造函数完成对象初始化；malloc 是库函数，只从堆上划出指定字节的原始内存、不调用构造函数、不初始化；②类型安全与用法——new 直接返回具体类型指针（`Node* p = new Node;`）、自动按类型算大小；malloc 返回 void*、需显式强转与 sizeof 计算（C 中不需强转、C++ 中必须）；③失败行为——new 分配失败抛 std::bad_alloc（nothrow 版返回 0）；malloc 失败返回 NULL、必须判空；④释放配对——new 配 delete、new[] 配 delete[]（会调用析构）；malloc 配 free（只还内存不调析构）；混用是未定义行为（如 free 释放 new 的内存、delete 释放 malloc 的内存都可能崩溃）；⑤构造/析构——new 先分配内存再调构造函数、delete 先调析构再释放内存，这是 C++ 对象生命周期管理的核心，malloc/free 做不到（对象内资源如文件句柄不会被自动释放）；⑥细节——new 可与构造异常配合自动回收内存；malloc 可与 realloc/calloc 配合，适合 C 代码与 POD 数据。关系：new/delete 底层通常用 malloc/free 实现（operator new 默认调用 malloc），二者是“内存分配”与“对象构造/析构”两个层面的功能；C++ 对象一律用 new/delete，只有需要原始字节缓冲、与 C 接口交互时才用 malloc/free。补充：还有 std::allocator、智能指针（unique_ptr/shared_ptr）管理生命周期。易错点：把 new 说成“只是带初始化的 malloc”、忽略析构与配对。", "区别：①new 是运算符——分配内存并调用构造函数完成初始化；malloc 是库函数——只分配原始内存、不构造不初始化。②new 返回具体类型指针、自动算大小；malloc 返回 void*、需强转+sizeof。③new 失败抛 std::bad_alloc（nothrow 返回 0）；malloc 失败返回 NULL 须判空。④配对：new/delete、new[]/delete[]（delete 调析构）；malloc/free（不调析构）；混用是未定义行为。⑤delete 先析构再释放内存，是对象生命周期管理的核心。关系：new/delete 底层通常基于 malloc/free（operator new 默认调 malloc），二者是“分配”与“构造/析构”两个层面；对象用 new/delete，原始缓冲/与 C 交互用 malloc/free。"),
}

if __name__ == "__main__":
    need = [466, 467, 468, 469, 470, 471, 472, 473, 474, 475, 476, 477, 478, 479, 480,
            481, 482, 483, 484, 485, 486, 487, 488, 489, 490, 491]
    assert sorted(NEW.keys()) == need, "题号集合不符"
    bad = []
    for n, (a, b) in NEW.items():
        for name, s in (("ana", a), ("ans", b)):
            if "\n" in s or "\r" in s or "**" in s or "```" in s or s.strip() != s or any(ord(c) < 32 for c in s):
                bad.append((n, name))
    print("题号齐全 OK，共", len(NEW), "题" if not bad else ("异常: " + str(bad)))
